int IsPalindrome(char *word)
{
    int left = 0;
    int right = strlen(word) - 1;

    while (left < right) {
        if (word[left] != word[right]) {
            return 0; 
        }
        left++;
        right--;
    }

    return 1; 

},"If the input word is 'radar', what are the values of 'left' and 'right' immediately before the while loop terminates?","If the input word is 'apple', at which index does the first mismatch occur, and what is the return value of the function?","left = 2, right = 2",Index 0 ('a') and index 4 ('e') mismatch

