int IsPalindrome(char *word)
{
    int length = strlen(word);
    int middle = (length - 1)/2;
    int counter = 0;

    if (length <= 1) {
        return 1;
    }

    if (length == 2) {
        if (word[0] == word[1]) {
            return 1;
        } else {
            return 0;
        }
    }

    for (int i = 0; i < middle; i++) {
        if (word[i] == word[length - 1 - i]) {
            counter++;
        }
    }

    int ispalindrome = 0;
    if (counter == middle) {
        ispalindrome = 1;
    }
    return ispalindrome;
},"If the input word is 'racecar', what is the value of the variable 'middle' and how many times will the for-loop execute?","If the input word is 'noon', which if-statement block is entered first, and what value does the function return?","middle is 3, and the loop will execute 3 times (for i = 0, 1, 2).",The 'if (length == 2)' block is skipped because length is 4

