int IsPalindrome(char *word)
{
    int i = 0;
    int j = 0;
    int test = 0;

    while (word[i] != '\0') {
        i++; //counts then number of characters till null ie abcba would be 5
    }
    if (i == 1) {
        return test = 1; //if only one letter, then always true
    }


    for (j = 0; j < i/2; j++) { // from 0 to i/2 and from i to i/2
        if (word[j] == word [i-j-1]) {
            test = 1;
        }
        else {
            test = 0;
            return test;
        }
    }
    return test;
},"If the input string is 'racecar', what is the value of the variable 'i' after the while loop finishes executing?","If the input string is 'apple', at which index 'j' does the for loop first encounter the 'else' block and return 0?",7,0,"#include <stdio.h>

