int IsPalindrome(char *word)
{
    int stringSize, checkUpperLimit;
    int i;

    // Determine the size of the string and how many
    // characters to check.
    stringSize = strlen(word);
    checkUpperLimit = stringSize / 2;

    // Check for any cases which make the word not a palindrome
    for (i = 0; i < checkUpperLimit; i++) {
        if (word[i] != word[stringSize - i - 1]) {
            return 0;
        }
    }

    // If program makes it this far, word must be a palindrome.
    return 1;
},"If the input word is 'radar', what is the value of checkUpperLimit and how many times will the for loop iterate?","If the input word is 'apple', at which value of the loop index 'i' will the function first return 0?","checkUpperLimit is 2, and the loop will iterate 2 times (i = 0 and i = 1).","The function will return 0 when i = 0, because word[0] ('a') is not equal to word[4] ('e').","#include <stdio.h>

