int IsPalindrome(char *word)
{
    int length = strlen(word);
    int isPalidrome = 0;
    int opposite = length - 1;
    int counter = 0;

    for (int i = 0; i < length/2; i++) {
        if (word[i] == word[opposite]) {
            counter++;
        }
        opposite--;
    }

    if (counter == length/2) {
        isPalidrome = 1;
    }

    return isPalidrome;
},"If the input word is 'radar', what is the value of the variable 'counter' immediately after the for-loop finishes executing?","If the input word is 'apple', what is the value of the variable 'opposite' during the second iteration of the for-loop (when i = 1)?",2,3,"#include <stdio.h>

