void ReverseString(char *str)
{
    int l = strlen(str);
    char newstr[l+1];
    int m = 0;
    for (int i = l-1; i >= 0; i--) {
        newstr[m] = str[i];
        m++;
    }
    newstr[m] = '\0';
    strcpy(str, newstr);
}

